arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -d "token=<TOKEN>&limit=0" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print(d); sys.exit(1)
for u in d['members']:
    if u.get('is_owner') or u.get('is_admin'):
        print(u.get('id'), u.get('profile',{}).get('real_name'), u.get('profile',{}).get('display_name'), 'owner' if u.get('is_owner') else '', 'admin' if u.get('is_admin') else '')
"

